import { writeFileSync } from 'node:fs';

// Keep the sequence monotonic across releases. The ASCII id must fit the
// 12-byte normal-mode response, including its trailing zero padding.
const [sequence, output = 'firmware/v2/src/studio_release.h'] = process.argv.slice(2);
if (!/^20\d{8}$/.test(sequence ?? '') || Number(sequence) > 0xffffffff) {
  throw Error('Usage: node scripts/build-firmware-identity.mjs YYYYMMDDNN [output]');
}
const stamp = sequence.slice(2, 8);
const revision = Number(sequence.slice(8));
writeFileSync(output, `// SPDX-License-Identifier: GPL-2.0-or-later
// Generated by scripts/build-firmware-identity.mjs.
#pragma once
#define ATHENA_RELEASE_SEQUENCE ${sequence}u
#if defined(PRODUCT_ID) && PRODUCT_ID == 0x2513
#define ATHENA_RELEASE_PID 0x2513
#define ATHENA_RELEASE_BUILD "75-${stamp}-${revision}"
#elif defined(PRODUCT_ID) && PRODUCT_ID == 0x4100
#define ATHENA_RELEASE_PID 0x4100
#define ATHENA_RELEASE_BUILD "18-${stamp}-${revision}"
#endif
`);
